"""Monthly sector allocation from cointegrated log-volatility forecasts.

Paper: Gabriele Casto (2025), https://arxiv.org/abs/2509.23533
statsmodels VECM library (BSD-3-Clause), used through its public API:
https://github.com/statsmodels/statsmodels/blob/main/statsmodels/tsa/vector_ar/vecm.py
https://github.com/statsmodels/statsmodels/blob/main/LICENSE.txt
https://www.statsmodels.org/stable/generated/statsmodels.tsa.vector_ar.vecm.VECM.html
https://www.statsmodels.org/stable/generated/statsmodels.tsa.vector_ar.vecm.VECMResults.predict.html
https://pypi.org/project/statsmodels/
Method references, with no notebook code copied:
https://github.com/tommasozeri/Financial-Econometrics-Models/blob/main/VECM.ipynb
https://www.quantconnect.com/docs/v2/research-environment/applying-research/kalman-filters-and-stat-arb
Public data client: https://github.com/ranaroussi/yfinance
"""

import gzip
import hashlib
import json
import signal
import warnings
from collections import Counter
from datetime import datetime
from io import BytesIO
from pathlib import Path

import numpy as np
import pandas as pd
import yaml
from statsmodels.tsa.vector_ar.vecm import VECM, coint_johansen
from threadpoolctl import threadpool_limits


ROOT = Path(__file__).resolve().parent
PRICE_FIELDS = ["Open", "Close", "Distributions", "Stock Splits"]
SESSIONS_PER_YEAR = 252


def load_prices(symbols, start, end, config):
    key = json.dumps([symbols, str(start.date()), str(end.date())])
    digest = hashlib.sha256(key.encode()).hexdigest()[:16]
    name = f"yahoo_daily_actions_{digest}.csv.gz"
    snapshot = config["data"]["snapshots"][name]
    cache_bytes = gzip.decompress(snapshot["gzip"])
    data_sha256 = hashlib.sha256(cache_bytes).hexdigest()
    if data_sha256 != snapshot["sha256"]:
        raise ValueError(f"SHA-256 mismatch for snapshot {name}")
    raw = gzip.decompress(cache_bytes)
    with BytesIO(raw) as file:
        stamp = file.readline().decode("utf-8").strip()
        prices = pd.read_csv(file, header=[0, 1], index_col=0, parse_dates=[0])
    if datetime.fromisoformat(stamp).utcoffset() is None:
        raise ValueError("Price download timestamp must include its UTC offset")
    index = prices.index
    if (not isinstance(index, pd.DatetimeIndex) or index.empty or index.hasnans
            or not index.is_unique or not index.is_monotonic_increasing
            or (index.day_of_week > 4).any() or index[0] < start or index[-1] > end
            or index[0] > start + pd.Timedelta(days=7)
            or index[-1] < end - pd.Timedelta(days=7)):
        raise ValueError("Yahoo Finance daily sample has invalid or incomplete dates")
    for symbol in symbols:
        values = prices[symbol][PRICE_FIELDS].to_numpy(dtype=float)
        if not np.isfinite(values).all() or (values[:, :2] <= 0).any() or (values[:, 2:] < 0).any():
            raise ValueError(f"Missing sessions or invalid prices/distributions for {symbol}")
    input_sha256 = hashlib.sha256(raw.partition(b"\n")[2]).hexdigest()
    print("Data source: Yahoo Finance (finance.yahoo.com) daily bars and corporate actions "
          "from yfinance with auto_adjust=False, embedded in config under data.snapshots "
          f"(decompressed sha256 {data_sha256}); the script does not call yfinance, FRED or "
          "any host and reads no data_cache")
    print(f"Input SHA-256: {input_sha256} (bytes hashed: the inner decompressed CSV body after the first-line timestamp; not the gzip cache and not the YAML !!binary wrapper)")
    print(f"DATA_SHA256: {data_sha256} (bytes hashed: the original cache file after removing the YAML !!binary gzip wrapper, i.e. the outer gzip-compressed cache bytes, not the raw CSV)")
    print("MARKET_DATA_SNAPSHOT: " + json.dumps({
        "path": "config.yaml", "key": "data.snapshots", "name": name, "sha256": data_sha256,
    }))
    return prices, stamp


def trace_rank(window, lag):
    try:
        with warnings.catch_warnings():
            # NumPy may return a complex dtype for an entirely real spectrum.
            warnings.simplefilter("ignore", np.exceptions.ComplexWarning)
            test = coint_johansen(window, det_order=0, k_ar_diff=lag)
    except np.linalg.LinAlgError:
        return None
    eigenvalues = np.real_if_close(test.eig)
    if not np.isrealobj(eigenvalues) or not np.isfinite(test.trace_stat).all():
        return None
    # The middle column of the Johansen table is the 5% critical value.
    stop = np.flatnonzero(test.trace_stat < test.trace_stat_crit_vals[:, 1])
    return int(stop[0]) if stop.size else window.shape[1]


def forecast_volatility(window, config):
    last = window[-1, :-1]
    lag = config["lagged_differences"]
    rank = trace_rank(window, lag)
    try:
        fit = VECM(window, k_ar_diff=lag, coint_rank=window.shape[1] - 1,
                   deterministic="ci").fit()
        predicted = fit.predict(steps=config["forecast_sessions"])[:, :-1]
    except (np.linalg.LinAlgError, FloatingPointError):
        return np.exp(last), rank, True
    max_move = np.log(config["forecast_guard_multiple"])
    if (not np.isrealobj(predicted) or not np.isfinite(predicted).all()
            or np.any(np.abs(predicted - last) > max_move)):
        return np.exp(last), rank, True
    return np.sqrt(np.mean(np.exp(2.0 * predicted), axis=0)), rank, False


def monthly_targets(log_returns, start, config, persistence=False):
    vol_window = config["volatility_window"]
    fit_window = config["fit_window"]
    if type(vol_window) is not int or vol_window < 2:
        raise ValueError("Volatility window must be an integer of at least two sessions")
    if type(fit_window) is not int or fit_window <= config["lagged_differences"] + 1:
        raise ValueError("Fit window must allow both levels and lagged differences")
    log_vol = np.log(log_returns.rolling(vol_window).std().clip(lower=1e-8))
    samples = log_vol.to_numpy()
    dates = log_vol.index
    months = dates.to_period("M")
    targets = {}
    diagnostics = []
    for fill in range(max(1, dates.searchsorted(start)), len(dates)):
        if months[fill] == months[fill - 1]:
            continue
        signal_row = fill - config["signal_lag_sessions"]
        left = signal_row - fit_window + 1
        if left < vol_window - 1:
            raise ValueError(f"Insufficient warmup before {dates[fill].date()}")
        window = samples[left:signal_row + 1]
        if persistence:
            forecast = np.exp(window[-1, :-1])
            rank, fallback = None, False
        else:
            forecast, rank, fallback = forecast_volatility(window, config)
        inverse = 1.0 / forecast
        targets[dates[fill]] = inverse / inverse.sum()
        diagnostics.append((dates[fill], dates[signal_row], rank, fallback))
    return targets, diagnostics


def rebalance_at_open(open_values, cash, weights, fee_rate):
    before = cash + open_values.sum()
    changes = weights * before - open_values
    tiny = before * 1e-12
    sells = np.where(changes < -tiny, -changes, 0.0)
    buys = np.where(changes > tiny, changes, 0.0)
    cash += sells.sum() * (1.0 - fee_rate)
    required = buys.sum() * (1.0 + fee_rate)
    if required > 0:
        debit = min(required, cash)
        buys *= debit / required
        cash -= debit
    traded = buys + sells
    return open_values - sells + buys, cash, traded.sum() / before, (traded > tiny).sum()


def simulate(opens, closes, references, start, targets, fee_rate):
    dates = opens.index
    first = dates.searchsorted(start)
    open_prices = opens.to_numpy()
    close_prices = closes.to_numpy()
    reference_prices = references.to_numpy()
    positions = np.zeros(opens.shape[1])
    cash, last_value = 1.0, 1.0
    rows = []
    for row in range(first, len(dates)):
        open_values = positions * (open_prices[row] / reference_prices[row])
        turnover, trades = 0.0, 0
        weights = targets.get(dates[row])
        if weights is not None:
            # Dollar fills at the reference open correspond to fractional units.
            open_values, cash, turnover, trades = rebalance_at_open(
                open_values, cash, weights, fee_rate,
            )
        if cash < 0 or (open_values < 0).any():
            raise ArithmeticError("Simulated fills exceeded cash or went short")
        positions = open_values * (close_prices[row] / open_prices[row])
        value = cash + positions.sum()
        rows.append((value / last_value - 1.0, turnover, trades))
        last_value = value
    return pd.DataFrame(rows, index=dates[first:], columns=["return", "turnover", "n_trades"])


def metrics(daily, risk_free):
    if len(daily) < 2:
        raise ValueError("Each evaluation period needs at least two sessions")
    returns = daily["return"]
    excess = returns - risk_free.loc[returns.index]
    growth = (1.0 + returns).cumprod()
    years = len(growth) / SESSIONS_PER_YEAR
    annualize = np.sqrt(SESSIONS_PER_YEAR)
    stdev = returns.std()
    excess_stdev = excess.std()
    return {
        "cagr": float(growth.iloc[-1] ** (1 / years) - 1),
        "ann_vol": float(stdev * annualize),
        "sharpe": float(returns.mean() * annualize / stdev) if stdev > 0 else None,
        "sharpe_excess": (float(excess.mean() * annualize / excess_stdev)
                          if excess_stdev > 0 else None),
        "max_drawdown": float((growth / growth.cummax().clip(lower=1.0) - 1.0).min()),
        "total_return": float(growth.iloc[-1] - 1.0),
        "turnover": float(daily["turnover"].sum()),
        "n_trades": int(daily["n_trades"].sum()),
    }


def run_robustness(log_returns, opens, closes, references, risk_free, start, config, fee_rate):
    variants = [
        (parameter, value)
        for parameter in ("volatility_window", "fit_window")
        for value in config["robustness"][parameter + "s"]
    ]
    if (len(variants) != len(set(variants))
            or any(config[parameter] == value for parameter, value in variants)):
        raise ValueError("Robustness variants must be distinct from each other and the default")
    print("ROBUSTNESS (IS only)")
    for parameter, value in [*variants, ("persistence", True)]:
        trial_config = {**config, parameter: value}
        targets, _ = monthly_targets(log_returns, start, trial_config,
                                     persistence=parameter == "persistence")
        daily = simulate(opens, closes, references, start, targets, fee_rate)
        print(f"  {parameter}={value} " + json.dumps(metrics(daily, risk_free), allow_nan=False))
    return len(variants) + 1


def print_diagnostics(diagnostics, is_end):
    for label, in_sample in [("IS", True), ("OOS", False)]:
        subset = [entry for entry in diagnostics if (entry[0] <= is_end) == in_sample]
        if not subset or all(entry[3] for entry in subset):
            raise RuntimeError(f"No model forecasts reached fills in {label}")
        if any(signal_date >= fill_date for fill_date, signal_date, _, _ in subset):
            raise RuntimeError("A forecast was used before its signal close")
        ranks = Counter("missing" if rank is None else str(rank) for _, _, rank, _ in subset)
        fallbacks = sum(entry[3] for entry in subset)
        print(f"VECM_{label}: scheduled={len(subset)} fallback={fallbacks} "
              f"trace_ranks={json.dumps(ranks, sort_keys=True)}")


def main():
    config = yaml.safe_load((ROOT / "config.yaml").read_text(encoding="utf-8"))
    universe = config["universe"]
    market, risk_free_symbol = config["market_proxy"], config["risk_free_symbol"]
    symbols = [*universe, market, risk_free_symbol]
    if len(universe) < 2 or len(symbols) != len(set(symbols)):
        raise ValueError("Choose distinct sector, market and cash-proxy symbols")
    if len(universe) + 1 > 12:
        raise ValueError("Statsmodels trace critical values support up to 12 series")
    data_start, start, is_end, end = (
        pd.Timestamp(config[key]) for key in ("data_start", "backtest_start", "is_end", "end_date")
    )
    if not data_start < start <= is_end < end:
        raise ValueError("Dates must allow warmup followed by separate IS and OOS evaluation")
    for key in ("signal_lag_sessions", "forecast_sessions", "lagged_differences"):
        if type(config[key]) is not int or config[key] < 1:
            raise ValueError(f"{key} must be a positive integer")
    cost, slippage = config["cost_bps"], config["slippage_bps"]
    fee_rate = (cost + slippage) / 10_000
    if min(cost, slippage) < 0 or not 0 <= fee_rate < 1:
        raise ValueError("Cost and slippage must be nonnegative with a sum below 100%")
    if not 1 < config["forecast_guard_multiple"] < np.inf:
        raise ValueError("Forecast guard multiple must be finite and greater than one")

    prices, stamp = load_prices(symbols, data_start, end, config)
    opens = prices.xs("Open", axis=1, level=1)
    closes = prices.xs("Close", axis=1, level=1)
    distributions = prices.xs("Distributions", axis=1, level=1)
    # Yahoo historical prices and distributions already use split-normalized units.
    references = closes.shift(1) - distributions
    if (references.iloc[1:] <= 0.0).any().any():
        raise ValueError("A distribution exceeded its previous closing price")
    close_returns = closes / references
    log_returns = np.log(close_returns[[*universe, market]]).iloc[1:]
    first = opens.index.searchsorted(start)
    if not 0 < first < len(opens):
        raise ValueError("Backtest needs at least one session after warmup")
    risk_free = close_returns[risk_free_symbol].iloc[first:].copy() - 1.0
    risk_free.iloc[0] = closes[risk_free_symbol].iloc[first] / opens[risk_free_symbol].iloc[first] - 1

    print(f"DATA_FETCHED_AT: {stamp}")
    print("PRICE_ADJUSTMENT: yfinance split-normalized bars, causal ex-date total-return ratios")
    with threadpool_limits(limits=1, user_api="blas"):
        alternatives = run_robustness(
            log_returns.loc[:is_end], opens.loc[:is_end, universe], closes.loc[:is_end, universe],
            references.loc[:is_end, universe], risk_free.loc[:is_end], start, config, fee_rate,
        )
        targets, diagnostics = monthly_targets(log_returns, start, config)
    print_diagnostics(diagnostics, is_end)

    daily = simulate(opens[universe], closes[universe], references[universe], start, targets, fee_rate)
    benchmark = simulate(opens[[market]], closes[[market]], references[[market]], start,
                         {daily.index[0]: np.ones(1)}, fee_rate)
    periods = {"is": daily.loc[:is_end], "oos": daily.loc[daily.index > is_end], "full": daily}
    result = {
        "strategy": config["strategy"],
        "data_range": f"{daily.index[0].date()} to {daily.index[-1].date()}",
        **{label: metrics(period, risk_free) for label, period in periods.items()},
        "benchmark": {"name": f"{market} buy and hold", **metrics(benchmark, risk_free)},
    }
    if any(result[label]["n_trades"] <= 0 for label in ("is", "oos", "full")):
        raise RuntimeError("Official strategy did not execute trades in each period")
    print(f"PARAM_COMBOS_TRIED: {alternatives + 1}")
    print("STATUS: 已回测")
    for label, period in periods.items():
        print(f"{label.upper()} ({period.index[0].date()} to {period.index[-1].date()}): "
              + json.dumps(result[label], allow_nan=False))
    print("BENCHMARK: " + json.dumps(result["benchmark"], allow_nan=False))
    print("RESULTS_JSON: " + json.dumps(result, allow_nan=False))


if __name__ == "__main__":
    signal.alarm(14 * 60)
    main()
